script_name("Помощник онлайн")
script_author("Помощник онлайн")
script_version("2.27")

local _update_marker = 'SHISHANI_ONE_FILE_AUTOUPDATER'
local _compat_blob = [[]]
_compat_blob = nil
local moonloader = require('moonloader')
local encoding = require('encoding')
encoding.default = 'CP1251'
local utf8 = encoding.UTF8
local status = moonloader.download_status
local dir = getWorkingDirectory() .. '\\resource'
local mp3 = dir .. '\\pomoshnik_music.mp3'
local temp = mp3 .. '.download'
local scriptTmp = getWorkingDirectory() .. '\\pomoshnik_restore.tmp'
local repo = 'https://raw.githubusercontent.com/Selvatore5747/Khavaji/master/shishani-center/'
local songUrl = repo .. 'music.mp3'
local versionUrl = repo .. 'version.txt'
local scriptUrl = repo .. 'pomoshnik.lua'
local checking = false

local function validMp3(path)
    local f = io.open(path, 'rb')
    if not f then return false end
    local size = f:seek('end') or 0
    f:seek('set')
    local first = f:read(3) or ''
    f:close()
    if size < 500000 then return false end
    return first == 'ID3' or (first:byte(1) == 0xFF and ((first:byte(2) or 0) >= 0xE0))
end

local function downloadSong()
    if validMp3(mp3) then return true end
    if not doesDirectoryExist(dir) then createDirectory(dir) end
    if doesFileExist(temp) then os.remove(temp) end
    local done, dataEnd = false, false
    local ok = pcall(downloadUrlToFile, songUrl, temp, function(id, event)
        if event == status.STATUS_ENDDOWNLOADDATA then dataEnd = true end
        if event == status.STATUSEX_ENDDOWNLOAD then done = true end
    end)
    if not ok then return false end
    local started = getGameTimer()
    while not done and getGameTimer() - started < 90000 do wait(250) end
    if not done or not dataEnd or not validMp3(temp) then
        if doesFileExist(temp) then os.remove(temp) end
        return false
    end
    if doesFileExist(mp3) then os.remove(mp3) end
    return os.rename(temp, mp3) and true or false
end

local function checkUpdate()
    if checking then return end
    checking = true
    local vtmp = getWorkingDirectory() .. '\\pomoshnik_version.tmp'
    local received = false
    if doesFileExist(vtmp) then os.remove(vtmp) end
    pcall(downloadUrlToFile, versionUrl .. '?t=' .. tostring(getGameTimer()), vtmp, function(_, event)
        if event == status.STATUS_ENDDOWNLOADDATA or event == status.STATUSEX_ENDDOWNLOAD then
            received = true
        end
    end)
    local start = getGameTimer()
    while not received and getGameTimer() - start < 12000 do wait(200) end
    if not received then checking = false return end
    local f = io.open(vtmp, 'rb')
    local remote = f and (f:read('*a') or '') or ''
    if f then f:close() end
    os.remove(vtmp)
    local version = tonumber(remote:match('^%s*(%d+%.%d+)'))
    if not version or version <= 2.27 then checking = false return end
    local finished = false
    if doesFileExist(scriptTmp) then os.remove(scriptTmp) end
    pcall(downloadUrlToFile, scriptUrl .. '?t=' .. tostring(getGameTimer()), scriptTmp, function(_, event)
        if event == status.STATUS_ENDDOWNLOADDATA or event == status.STATUSEX_ENDDOWNLOAD then
            finished = true
        end
    end)
    local started = getGameTimer()
    while not finished and getGameTimer() - started < 25000 do wait(200) end
    local script = nil
    if finished then
        local sf = io.open(scriptTmp, 'rb')
        if sf then script = sf:read('*a') sf:close() end
    end
    if not script or not script:find('script_version("' .. tostring(version) .. '")', 1, true)
        or not script:find('SHISHANI_ONE_FILE_AUTOUPDATER', 1, true) then
        if doesFileExist(scriptTmp) then os.remove(scriptTmp) end
        checking = false
        return
    end
    local ok, converted = pcall(function() return utf8:decode(script) end)
    if not ok or not converted or not loadstring(converted, '@pomoshnik.lua') then
        checking = false
        return
    end
    script = converted
    local current = thisScript().path
    local backup = current .. '.bak'
    local src = io.open(current, 'rb')
    if src then
        local bytes = src:read('*a')
        src:close()
        local bk = io.open(backup, 'wb')
        if bk then bk:write(bytes) bk:close() end
    end
    local target = io.open(current, 'wb')
    if target then
        target:write(script)
        target:close()
        os.remove(scriptTmp)
        checking = false
        thisScript():reload()
        return
    end
    checking = false
end

function main()
    while not isSampAvailable() do wait(250) end
    lua_thread.create(function()
        wait(3500)
        while true do
            checkUpdate()
            wait(180000)
        end
    end)
    while not validMp3(mp3) do
        if downloadSong() then break end
        wait(15000)
    end
    local success, a, b = pcall(loadAudioStream, mp3)
    local handle = type(a) == 'number' and a or (type(b) == 'number' and b or nil)
    if not success or not handle or handle == 0 then return end
    setAudioStreamLooped(handle, true)
    setAudioStreamState(handle, moonloader.audiostream_state.PLAY)
    while true do
        wait(1000)
    end
end
